SELECT COUNT(DISTINCT t0.o) AS "count_result" FROM triples t0, triples t1, triples t2 WHERE t0.s = 'http://db.uwaterloo.ca/~galuc/wsdbm/City137' AND t0.p = 'http://www.geonames.org/ontology#parentCountry' AND t1.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/likes' AND t1.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/Product0', datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://schema.org/nationality' AND t2.o = t0.o